const input = $input.first().json.body || $input.first().json;
if (!Array.isArray(input.logs)) throw new Error('logs array is required');
const logs = input.logs.slice(0, 500).map(e => ({ turnstileId: e.turnstileId ?? null, turnstileName: e.turnstileName || null, personType: e.personType || 'UNKNOWN', unitNumber: e.unitNumber || null, accessDecision: e.accessDecision || 'UNKNOWN', failureReason: e.failureReason || null, timestamp: e.timestamp || null, confidenceScore: e.confidenceScore == null ? null : Number(e.confidenceScore) }));
const counts = { total: logs.length, granted: logs.filter(e => e.accessDecision === 'GRANTED_OPEN').length, denied: logs.filter(e => String(e.accessDecision).startsWith('DENIED')).length, lockdownDenials: logs.filter(e => e.accessDecision === 'DENIED_LOCKDOWN').length };
const prompt = `Review these biometric turnstile access-log events for operational anomalies. Do not identify or profile individuals, infer intent, or recommend punitive action. Aggregate repeated denials and device issues; flag possible sensor or configuration problems. Never command a relay, unlock/lock gate, enroll a person, or change access. Provide a human verification checklist.
Counts=${JSON.stringify(counts)}
Events=${JSON.stringify(logs)}
Return JSON {"reviewLevel":"NORMAL|ATTENTION|URGENT","summary":"...","deviceChecks":["..."],"accessPolicyChecks":["..."],"dataLimitations":["..."],"humanReviewRequired":true}.`;
return [{ json: { communityId: input.communityId || null, reviewedWindow: input.reviewedWindow || null, counts, prompt } }];
